SELECT COUNT(*) FROM users as u, comments as c, postLinks as pl, postHistory as ph, votes as v, posts as p WHERE u.Id = c.UserId AND p.Id = c.PostId AND p.Id = pl.PostId AND p.Id = ph.PostId AND u.Id = v.UserId AND u.Reputation<=270 AND u.Views>=0 AND u.Views<=51 AND u.DownVotes>=0 AND c.Score=0 AND c.CreationDate>=CAST('2010-08-02 20:27:48' AS TIMESTAMP) AND c.CreationDate<=CAST('2014-09-10 16:09:23' AS TIMESTAMP) AND pl.CreationDate>=CAST('2011-11-03 05:09:35' AS TIMESTAMP) AND ph.PostHistoryTypeId=1
